// Calabi-Yau SOLIDA: sezione 2D della quintica di Fermat, ispessita in un guscio.
//   z1^n + z2^n = 1,  z1,z2 complessi;  n = grado, dallo slider A.
// Le 25 griglie sono il massimo (5x5); il cutout scarta quelle che sforano il
// grado scelto (indici SEMPRE in base 5: sopravvivono le patch con entrambi < n).
//
// SPESSORE: la lamina viene sdoppiata lungo la normale, +C/2 e -C/2. Il segno lo
// decide v: meta' inferiore del dominio = faccia interna, meta' superiore =
// esterna. Una sola griglia produce le due facce. Il bordo resta aperto.
//
// NB: niente funzioni ausiliarie -- il corpo e' iniettato DENTRO getRawPosition
// e GLSL non ammette funzioni annidate. I tre campionamenti (punto, +h in u,
// +h in v) sono quindi scritti per esteso.

A := int(2,5);
MESH_VISIBLE := A*A;

float n  = clamp(floor(A + 0.5), 2.0, 5.0);
float k1 = mod(float(mesh), 5.0);
float k2 = floor(float(mesh) / 5.0);
float pw = 2.0 / n;
float a1 = 2.0 * pi * k1 / n;
float a2 = 2.0 * pi * k2 / n;

// v ripiegata: |v| e' il parametro vero, il segno sceglie la faccia
float vs = sign(v) + step(abs(v), 0.0);   // +1 / -1, mai 0
float vv = -1.0 + 2.0 * abs(v);
float h  = 0.004;

// --- campionamento al punto e nei due vicini (u+h, vv+h) ---
vec3 P0, Pu, Pv;
for (int q = int(0.0); q < int(3.0); q++) {
    float uu  = u  + h * step(0.5, float(q)) * step(float(q), 1.5);
    float vvv = vv + h * step(1.5, float(q));

    vec2 cw = vec2( cos(uu) * cosh(vvv), -sin(uu) * sinh(vvv));
    vec2 sw = vec2( sin(uu) * cosh(vvv),  cos(uu) * sinh(vvv));
    float rc = safePow(length(cw), pw);
    float tc = pw * atan(cw.y, cw.x);
    float rs = safePow(length(sw), pw);
    float ts = pw * atan(sw.y, sw.x);
    vec2 z1 = rc * vec2(cos(tc + a1), sin(tc + a1));
    vec2 z2 = rs * vec2(cos(ts + a2), sin(ts + a2));
    vec3 Pq = vec3(z1.x, z2.x, cos(B) * z1.y + sin(B) * z2.y);

    if (q == int(0.0)) { P0 = Pq; }
    if (q == int(1.0)) { Pu = Pq; }
    if (q == int(2.0)) { Pv = Pq; }
}

// Normale per differenze in avanti. Vicino a u = 0 la parametrizzazione si
// affolla e il prodotto vettoriale puo' degenerare: fallback a una costante,
// li' innocuo perche' la patch e' minuscola.
vec3 nr = cross(Pu - P0, Pv - P0);
float L = length(nr);
// Niente ternario e niente notazione esponenziale (1e-6): il traduttore
// riscrive i letterali e su entrambi inciampa. max() fa lo stesso lavoro --
// dove la normale degenera (u ~ 0, parametrizzazione affollata) il vettore
// resta minuscolo e lo spessore li' e' trascurabile, che e' innocuo.
nr = nr / max(L, 0.000001);

return vec4(P0 + nr * (vs * C * 0.5), 0.0);

//CUTOUT_BEGIN
float nc = clamp(floor(A + 0.5), 2.0, 5.0);
return (mod(float(mesh), 5.0) > nc - 0.5) || (floor(float(mesh) / 5.0) > nc - 0.5);
//CUTOUT_END
